import MiniSearch from 'minisearch';

/**
 * Biomi's "brain": free, in-browser search over the website's own content
 * (public/biomi-index.json, generated by scripts/build-biomi-index.js).
 * No AI and no server calls (except live job openings). It only ever shows
 * information that is on the website, and says so when it can't find an answer.
 */

export type Product = { name: string; brand: string; category: string; description: string; image: string; logo: string; url: string };
export type Faq = { category: string; q: string; a: string };
export type Office = { name: string; address: string; phone: string; email: string; hours: string };
type Index = { products: Product[]; faqs: Faq[]; offices: Office[] };

export type Answer = {
	text: string[];
	products?: Product[];
	offices?: Office[];
	jobs?: string[];
	links?: { label: string; href: string }[];
	suggestions?: string[];
};

export const STARTER_QUESTIONS = [
	'What products do you offer?',
	'Do you have hematology analyzers?',
	'How can I request a quotation?',
	'Where are your offices?',
];

// Query words mapped to extra search terms (English + common Filipino/Taglish).
const SYNONYMS: [RegExp, string][] = [
	[/\bcbc\b|\bblood count\b|\bhema\b/, 'hematology'],
	[/\bspinner|\bspin\b/, 'centrifuge'],
	[/\bfridge|\bref\b|\brefrigerator/, 'refrigerator biorefrigerators'],
	[/\bfreezer/, 'freezer'],
	[/\bxray|\bx-ray|\bx ray/, 'x-ray radiography radiology'],
	[/\bultrasound|\bsonograph/, 'ultrasound imaging'],
	[/\bventilator|\bvent\b/, 'ventilator pulmonary'],
	[/\bmicroscope/, 'microscope'],
	[/\bpcr\b|\bdna\b|\brna\b/, 'molecular nucleic pcr'],
	[/\ballergy|\ballergen/, 'allergy madx'],
	[/\bglucose|\bsugar\b/, 'glucose'],
	[/\bhba1c|\ba1c\b|\bdiabetes/, 'hba1c'],
	[/\bautoclave|\bsteriliz/, 'sterilizer autoclave'],
	[/\bpipet/, 'pipette pipettor'],
	[/\becg\b|\bekg\b/, 'ecg electrocardiograph'],
	[/\bbeckman\b/, 'beckman coulter'],
	[/\bthyroid|\btsh\b/, 'thyroid immunoassay'],
	[/\burine|\burinalysis/, 'urine urinalysis'],
];

const STOP = new Set(
	('a an the is are am do does did you your yours we our ours i me my of for to in on at by with and or ' +
		'have has had can could would should what which who whom where when how why any some about please ' +
		'there this that these those it its be been being from as want need looking look show tell know ' +
		'ba po ang ng mga sa may kayo ko ako niyo nyo si yung meron mayroon na ano paano pwede gusto').split(' '),
);

const norm = (s: string) => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '');
const tokens = (s: string) => norm(s).replace(/[^a-z0-9+\- ]/g, ' ').split(/\s+/).filter((t) => t && !STOP.has(t));

let loaded: Promise<{ data: Index; products: MiniSearch<Product & { id: number }>; faqs: MiniSearch<Faq & { id: number }> }> | null = null;

/** Load the index once (cached by the browser too). */
export function loadBiomi() {
	if (!loaded) {
		loaded = fetch('/biomi-index.json')
			.then((r) => r.json() as Promise<Index>)
			.then((data) => {
				const products = new MiniSearch<Product & { id: number }>({
					fields: ['name', 'brand', 'category', 'description'],
					storeFields: ['name'],
					searchOptions: { boost: { name: 4, brand: 3, category: 2, description: 0.6 }, fuzzy: 0.2, prefix: true, combineWith: 'OR' },
				});
				products.addAll(data.products.map((p, id) => ({ ...p, id })));
				const faqs = new MiniSearch<Faq & { id: number }>({
					fields: ['q', 'a', 'category'],
					storeFields: ['q'],
					searchOptions: { boost: { q: 3, category: 1.5, a: 0.8 }, fuzzy: 0.2, prefix: true, combineWith: 'OR' },
				});
				faqs.addAll(data.faqs.map((f, id) => ({ ...f, id })));
				return { data, products, faqs };
			})
			.catch((e) => {
				loaded = null;
				throw e;
			});
	}
	return loaded;
}

const has = (q: string, re: RegExp) => re.test(q);

async function jobOpenings(): Promise<string[]> {
	try {
		const r = await fetch('/api/job-positions');
		const j = await r.json();
		return Array.isArray(j?.data) ? j.data.map((p: { title: string }) => p.title) : [];
	} catch {
		return [];
	}
}

const faqAnswer = (data: Index, re: RegExp) => data.faqs.find((f) => re.test(f.q))?.a;

/** Answer a visitor's question using only website content. */
export async function askBiomi(question: string): Promise<Answer> {
	const { data, products, faqs } = await loadBiomi();
	const q = norm(question).trim();
	const words = tokens(question);

	// ---- small talk ----
	if (/^(hi|hello|hey|good (morning|afternoon|evening)|kumusta|musta)\b/.test(q) && words.length <= 3) {
		return { text: ['Hello! I can help you find Biosite products, brands, office locations, and more. What are you looking for?'], suggestions: STARTER_QUESTIONS };
	}
	if (/\b(thank|thanks|salamat|ty)\b/.test(q) && words.length <= 4) {
		return { text: ["You're welcome! Anything else I can help you find?"] };
	}

	// ---- offices / contact ----
	const cityOffice = data.offices.find((o) => q.includes(norm(o.name)) || (o.name === 'Manila' && /\b(san juan|metro manila|luzon|ncr)\b/.test(q)));
	if (has(q, /\b(contact|phone|number|call|tawag|email|e-mail|address|location|locations|office|offices|branch|where|saan|visit|hours|open|oras|bukas)\b/) || (cityOffice && words.length <= 3)) {
		const offices = cityOffice ? [cityOffice] : data.offices;
		return {
			text: [cityOffice ? `Here are the details for our ${cityOffice.name} office:` : 'We have offices in Manila, Cebu and Davao:'],
			offices,
			links: [{ label: 'Contact us', href: '/user/contact' }],
		};
	}

	// ---- careers ----
	if (has(q, /\b(job|jobs|hiring|career|careers|vacanc|opening|openings|apply|trabaho|work with|employment|hire)\w*/)) {
		const jobs = await jobOpenings();
		return {
			text: [
				jobs.length
					? `We're currently hiring for ${jobs.length} position${jobs.length === 1 ? '' : 's'}. You can apply on our Careers page by sending your résumé.`
					: 'You can apply on our Careers page by sending your résumé.',
			],
			jobs: jobs.slice(0, 10),
			links: [{ label: 'Go to Careers', href: '/user/career' }],
		};
	}

	// ---- pricing / quotation ----
	if (has(q, /\b(price|prices|pricing|cost|how much|magkano|presyo|quotation|quote|rfq|discount)\b/)) {
		const a = faqAnswer(data, /quotation|quote/i) || faqAnswer(data, /price|pricing/i);
		return {
			text: [a || 'Pricing depends on the product and configuration. Please request a quotation and our sales team will get back to you.'],
			links: [{ label: 'Request a Quote', href: '/user/contact' }],
		};
	}

	// ---- brand asked directly ----
	const brandNames = [...new Set(data.products.map((p) => p.brand).filter(Boolean))];
	const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
	const brand = brandNames.find((b) => {
		const nb = norm(b);
		const first = nb.split(' ')[0];
		// full brand name, or its first word when distinctive ("beckman" -> Beckman Coulter)
		return new RegExp(`\\b${esc(nb)}\\b`).test(q) || (first.length >= 5 && new RegExp(`\\b${esc(first)}\\b`).test(q));
	});
	// Brand-only questions ("Hermle", "do you carry Sakura products?") list the brand;
	// anything more specific ("sakura tissue processor") goes to the search below.
	const GENERIC = new Set(['product', 'products', 'brand', 'brands', 'carry', 'sell', 'offer', 'items', 'equipment', 'machines', 'machine']);
	const brandTokens = brand ? new Set(tokens(brand)) : new Set<string>();
	const leftover = words.filter((w) => !brandTokens.has(w) && !GENERIC.has(w) && !(brand && norm(brand).startsWith(w)));
	if (brand && leftover.length === 0) {
		const list = data.products.filter((p) => p.brand === brand);
		const cats = [...new Set(list.map((p) => p.category))];
		return {
			text: [`Yes — we carry ${brand}. ${list.length} product${list.length === 1 ? '' : 's'} in ${cats.join(', ')}.`],
			products: list.slice(0, 6),
			links: [...new Map(list.map((p) => [p.url, { label: `View ${p.category}`, href: p.url }])).values()].slice(0, 3),
		};
	}

	// ---- general search ----
	let expanded = words.join(' ');
	for (const [re, extra] of SYNONYMS) if (re.test(q)) expanded += ' ' + extra;
	if (!expanded.trim()) {
		return { text: ["Could you tell me a bit more about what you're looking for?"], suggestions: STARTER_QUESTIONS };
	}

	const pHits = products.search(expanded);
	const fHits = faqs.search(expanded);
	const topP = pHits[0]?.score ?? 0;
	const topF = fHits[0]?.score ?? 0;

	// "What do you offer / products overview" style questions are best answered by the FAQ.
	const wantsOverview = /\b(products?|offer|sell|carry|categories|catalog|items)\b/.test(q) && words.length <= 4 && !brand;
	const useFaq = topF > 0 && (wantsOverview || topF >= topP * 0.6) && topF > 6;
	const productsRelevant = pHits.filter((h) => h.score >= Math.max(topP * 0.45, 3)).slice(0, 4).map((h) => data.products[h.id as number]);

	// Company/service FAQs (about us, delivery, service...) shouldn't drag in product cards.
	const faqCat = useFaq ? data.faqs[fHits[0].id as number].category : '';
	const nonProductFaq = /about|ordering|shipping|delivery|service|support|career|contact|location/i.test(faqCat);

	if (useFaq || productsRelevant.length) {
		const ans: Answer = { text: [] };
		if (useFaq) ans.text.push(data.faqs[fHits[0].id as number].a);
		if (productsRelevant.length && !wantsOverview && !(useFaq && nonProductFaq)) {
			ans.text.push(useFaq ? 'Related products:' : 'Here’s what I found on our website:');
			ans.products = productsRelevant;
			ans.links = [...new Map(productsRelevant.map((p) => [p.url, { label: `View ${p.category}`, href: p.url }])).values()].slice(0, 2);
		}
		if (!ans.text.length) ans.text.push('Here’s what I found on our website:');
		return ans;
	}

	// ---- nothing found: be honest ----
	return {
		text: [
			"Sorry, I couldn't find that on our website. Try a product name, brand, or category — or contact our team and they'll be happy to help.",
		],
		suggestions: STARTER_QUESTIONS.slice(0, 3),
		links: [{ label: 'Contact us', href: '/user/contact' }],
	};
}
